Runtime: JavaScript ES modules, installed Node.js, standard-library node:test. Run node --test; no dependency installation or build step is needed.
The UI reads the boolean pending property, initially false. A submission sets pending before invoking save(signal); overlapping submissions on that same instance resolve undefined promptly and must not invoke their callback. Different instances remain independent. Preserve signal object identity, successful result identity and propagated error identity. Clear pending on every settled path, including synchronous invocation errors and rejected saves, so another submission can retry.
Cancellation belongs to the supplied callback: forward the signal unchanged, and when that callback rejects because its signal was aborted, propagate that exact reason and clear pending. Do not invent a new cancellation API, abort the caller's controller, or pretend the panel can force an abort-ignoring callback to settle. No browser rendering is provided or required; test the actual panel class.
Keep both existing tests and their assertions unchanged. Add regression coverage without editing unrelated files. Use local controlled promises/signals rather than network or arbitrary sleeps; every behavior-dependent wait needs a deadline, and tests own callback settlement, rejection handlers and cleanup.
import assert from 'node:assert/strict';
import test from 'node:test';
import { SubmitPanel } from './panel.mjs';

test('preserves result and signal identity', async () => {
  const panel = new SubmitPanel(), signal = new AbortController().signal, result = {};
  assert.equal(await panel.submit(async received => { assert.equal(received, signal); return result; }, signal), result);
});

test('preserves callback rejection identity', async () => {
  const error = new Error('save failed');
  await assert.rejects(new SubmitPanel().submit(async () => { throw error; }), reason => reason === error);
});
/**
 * Copy into permitted JavaScript test support when no equivalent exists.
 * No dependencies or application implementation; uses ordinary ES modules.
 *
 * const save = controlledCall();
 * const task = form.submit(save); // register rejection handling/cleanup now
 * const call = await save.started(1000); // actual entry, timeout in milliseconds
 * call.complete(result); // or call.fail(error); then await the application task
 *
 * Each call has unique identity even for identical args. args and receiver keep
 * references, not snapshots. save.calls records all entries. released means a
 * completion/failure was requested; Promise resolution still assimilates thenables.
 * Releasing twice throws. Test synchronous invocation errors with a normal
 * throwing function, not this Promise-returning double.
 *
 * Tests own application assertions, bounded application waits and cleanup:
 * handle rejected tasks promptly, release every unreleased call, then drain tasks.
 * A started timeout removes only that waiter; it does NOT cancel application
 * work. Promises have no implicit cancellation. Use the application's AbortSignal
 * path when testing cancellation. Timers cannot interrupt blocking JS; use runner
 * process deadlines where needed. No browser/network/rendering evidence is supplied.
 */
export function controlledCall() {
  const calls = [];
  const entries = [];
  const waiters = [];

  function callback(...args) {
    let resolve, reject;
    const promise = new Promise((yes, no) => { resolve = yes; reject = no; });
    let released = false;
    function release(action, value) {
      if (released) throw new Error('Controlled call already released');
      released = true;
      action(value);
    }
    const call = {
      args, receiver: this,
      get released() { return released; },
      complete(value) { release(resolve, value); },
      fail(error) { release(reject, error); },
    };
    calls.push(call);
    const waiter = waiters.shift();
    if (waiter) {
      clearTimeout(waiter.timer);
      waiter.resolve(call);
    } else {
      entries.push(call);
    }
    return promise;
  }

  callback.calls = calls;
  callback.started = (timeoutMs = 1000) => {
    if (!Number.isFinite(timeoutMs) || timeoutMs <= 0 || timeoutMs > 30000) {
      throw new RangeError('timeoutMs must be in (0, 30000]');
    }
    if (entries.length) return Promise.resolve(entries.shift());
    return new Promise((resolve, reject) => {
      const waiter = { resolve, timer: undefined };
      waiter.timer = setTimeout(() => {
        waiters.splice(waiters.indexOf(waiter), 1);
        reject(new Error('Timed out waiting for callback entry'));
      }, timeoutMs);
      waiters.push(waiter);
    });
  };
  return callback;
}

export class SubmitPanel {
  async submit(save, signal) {
    return await save(signal);
  }
}

